function photo(name,alt,cls='',lazy=true){return `<div class="moving-photo ${cls}">${img(name,alt,'',lazy)}<span class="photo-corner">notfukuda</span></div>`}

const bookmark='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg>';
const estimatedPrice=n=>`<small class="estimated-price">ESTIMATED PRICE</small> ${yen(n)}`;
function likeButton(p,cls=''){const l=window.notfukudaLikes?.state,on=l?.liked.has(p.id)||false;return `<button class="purchase-like ${cls} ${on?'active':''}" data-action="like" data-id="${p.id}" data-name="${esc(p.name)}" aria-label="${esc(p.name)}${on?'の購入希望のいいねを取り消す':'に購入希望のいいねをする'}" aria-pressed="${on}">${heart}<span class="like-count" aria-live="polite">${l?.counts?l.counts[p.id].toLocaleString('ja-JP'):'—'}</span><span class="like-label">購入希望</span></button>`}
function card(p,context='shop'){const cover=p.image;const hover=context==='home'&&['020','022','023'].includes(p.id)?'exp-card-'+p.id+'.webp':p.wear;return `<article class="product-card"><div class="card-image"><a href="#/product/${p.id}" aria-label="${esc(p.name)} 詳細">${img(cover,p.jp)}${img(hover,(hover===p.image?'商品単体：':hover===p.wear?'モデル着用：':'別角度：')+p.jp,'wear-hover')}</a><button class="heart ${wish.includes(p.id)?'active':''}" data-action="wish" data-id="${p.id}" aria-label="${esc(p.name)}をお気に入り${wish.includes(p.id)?'から削除':'に追加'}" aria-pressed="${wish.includes(p.id)}">${bookmark}</button><span class="product-code">NF–${p.id}</span><button class="card-3d" data-action="object3d" data-id="${p.id}" aria-label="${esc(p.jp)}を3Dで見る">3D ↗</button></div><div class="card-meta"><a href="#/product/${p.id}"><h3>${p.name}</h3><p>${p.color} / ${p.cat}</p></a><span class="card-price">${estimatedPrice(p.price)}</span></div>${likeButton(p,'card-like')}</article>`}
